import session from 'express-session'
import connectPgSimple from 'connect-pg-simple'
import type { Request } from 'express'
import type { Pool } from 'pg'

const PgStore = connectPgSimple(session)

// Only a session generated by this middleware may insert its first row.
// Loaded sessions and subsequent saves use UPDATE, so DELETE wins regardless
// of whether a stale save executes before or after logout/expiry/regeneration.
export function sessionStore(pool: Pool) {
  const fresh = new WeakSet<session.SessionData>()
  class RevocationSafeStore extends PgStore {
    declare generate: (req: Request) => void
    override set(
      sid: string,
      value: session.SessionData,
      callback?: (error?: unknown) => void,
    ) {
      if (fresh.delete(value)) return super.set(sid, value, callback)
      const expires = value.cookie.expires
      if (!expires) return callback?.(new Error('Session expiration required'))
      void pool
        .query(
          'UPDATE "session" SET sess = $1, expire = to_timestamp($2) WHERE sid = $3 AND expire >= now()',
          [value, Math.ceil(new Date(expires).valueOf() / 1000), sid],
        )
        .then(
          () => callback?.(),
          () => callback?.(new Error('Session storage operation failed')),
        )
    }
  }
  const store = new RevocationSafeStore({
    pool,
    createTableIfMissing: false,
    errorLog: () => console.error('Session storage operation failed'),
  })
  // express-session installs generate() during session() construction. Wrap it
  // afterward, including Passport's regenerate() path; never infer freshness
  // from browser data, a missing database row, or process-local SID caches.
  function trackGeneration() {
    const generate = store.generate.bind(store)
    store.generate = (req) => {
      generate(req)
      fresh.add(req.session)
    }
  }
  return { store, trackGeneration }
}
